def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    if n < 8:
        return 'C' if last_opp == 'C' else 'D'

    cc = cd = dc = dd = 0
    for i in range(1, n):
        prev_me = history[i-1][0]
        curr_opp = history[i][1]
        if prev_me == 'C':
            if curr_opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if curr_opp == 'C':
                dc += 1
            else:
                dd += 1

    opp_def = sum(1 for a, b in history if b == 'D')
    my_def = sum(1 for a, b in history if a == 'D')

    if opp_def == 0 and my_def < 4 and n >= 10 and n % 10 == 0:
        return 'D'

    p_c_c = (cc + 1) / (cc + cd + 2)
    p_c_d = (dc + 1) / (dc + dd + 2)

    if p_c_d > 0.8 and n > 20:
        return 'D'

    if p_c_c < 0.3 and n > 20:
        return 'D'

    if p_c_c > 0.7 and p_c_d < 0.4:
        return 'C'

    if p_c_d < 0.3:
        return 'C'

    if p_c_d > 0.6:
        return 'D'

    if last_opp == 'D':
        if n > 30 and opp_def <= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'
    else:
        return 'C'
